import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, texture } from 'three/tsl';
import { gsap } from 'gsap';
import { } from '@/primitives';
import { } from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, DoubleSide } = ctx.THREE;

  // Root object for this node
  const root = new Group();

  // Use atlas region size; fallback to full image if not provided
  const region = (config.atlasRegion) || { width: 512, height: 320 };
  const aspect = region.width / region.height;

  // Plane geometry matched to aspect ratio
  const geometry = new PlaneGeometry(aspect, 1);

  // Basic node material (transparent to allow non‑full‑alpha textures)
  const material = new MeshBasicNodeMaterial({
    transparent: true,
    side: DoubleSide,
    depthWrite: false,
  });

  // Load texture via the provided loader (async but handled synchronously)
  let loadedTexture = null;
  const texPromise = ctx.textureLoader
    .loadTexture(config.imageUrl)
    .then((tex) => {
      loadedTexture = tex;
      // For MeshBasicNodeMaterial the classic map slot works
      material.map = tex;
      material.needsUpdate = true;
    })
    .catch(() => {
      // Fail silently – the node will remain invisible if texture fails
    });

  // Assemble mesh
  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Apply any cinematic primitives defined in the config
  const primitiveHandles = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (fn) {
        const handle = fn(root, prim.params || {});
        primitiveHandles.push(handle);
      }
    }
  }

  // No explicit interactions – expose empty handler bucket
  root.userData.handlers = {};

  // Cleanup routine
  root.userData.cleanup = () => {
    // Cancel any pending texture promise
    texPromise.catch(() => {});

    if (loadedTexture) {
      loadedTexture.dispose();
      loadedTexture = null;
    }
    material.dispose();
    geometry.dispose();

    // Dispose all primitive resources
    for (const ph of primitiveHandles) {
      if (ph && typeof ph.cleanup === 'function') {
        ph.cleanup();
      }
    }

    // Kill any GSAP timelines that might have been attached accidentally
    gsap.globalTimeline.clear();
  };

  return root;
}
